// === Tab: mySketch ===
/**
 * GENERADOR "TD-EMULATOR"
 * Características: Feedback Loop, Ruido Perlin Vectorial, Instancing Simulado, UI de Nodos.
 * Optimizado para OpenProcessing.
 */

let particulas = [];
let numParticulas = 400; // Equivalente a la cantidad de "Instancias"
let feedbackBuffer;      // Simula nuestro Feedback TOP
let zOff = 0;            // Desplazamiento Z para el ruido 3D (Evolución temporal)

// Configuración de "Nodos" (Parámetros)
let parametros = {
  escalaRuido: 0.005,
  fuerzaRuido: 2.5,
  velocidadEvolucion: 0.002,
  escalaFeedback: 1.003, // Mayor a 1 = expande, Menor a 1 = contrae
  alphaDesvanecimiento: 0.03
};

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1);

  // Inicializamos el "Feedback TOP" (Un lienzo invisible donde dibujamos los efectos)
  feedbackBuffer = createGraphics(windowWidth, windowHeight);
  feedbackBuffer.colorMode(HSB, 360, 100, 100, 1);
  feedbackBuffer.background(5, 100, 10); // Fondo oscuro muy saturado

  // Generamos nuestras partículas ("Geometría instanciada")
  for (let i = 0; i < numParticulas; i++) {
    particulas.push(new Particula());
  }

  textFont('monospace');
  background(5, 100, 10);
}

function draw() {
  // ==========================================
  // 1. FASE DE FEEDBACK TOP (Retroalimentación)
  // ==========================================
  feedbackBuffer.push();
  // Mover al centro, escalar (zoom in/out suave) y volver
  feedbackBuffer.translate(width / 2, height / 2);
  feedbackBuffer.scale(parametros.escalaFeedback);
  // Pequeña rotación para el efecto espiral
  feedbackBuffer.rotate(0.001); 
  feedbackBuffer.translate(-width / 2, -height / 2);

  // Aplicar un cuadro semitransparente para crear las estelas (Level TOP / Over TOP)
  feedbackBuffer.noStroke();
  feedbackBuffer.fill(5, 100, 10, parametros.alphaDesvanecimiento);
  feedbackBuffer.rect(0, 0, width, height);
  feedbackBuffer.pop();

  // ==========================================
  // 2. FASE DE CHOPs Y SOPs (Matemáticas y Dibujo)
  // ==========================================
  for (let p of particulas) {
    p.actualizar();
    p.dibujar(feedbackBuffer);
  }

  // Evolucionar el campo de ruido en el tiempo
  zOff += parametros.velocidadEvolucion;

  // ==========================================
  // 3. RENDER FINAL AL LIENZO PRINCIPAL (Out)
  // ==========================================
  // Dibujamos el resultado del buffer en la pantalla
  image(feedbackBuffer, 0, 0);

  // ==========================================
  // 4. UI OVERLAY (Estilo Interfaz TouchDesigner)
  // ==========================================
  dibujarUI();
}

// ------------------------------------------
// CLASE PARTICULA (Simulación de instancing impulsado por ruido)
// ------------------------------------------
class Particula {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.colorBase = random([
      color(180, 100, 100), // Cian
      color(300, 100, 100), // Magenta
      color(60, 100, 100)   // Amarillo Neón
    ]);
    this.grosor = random(1, 3);
  }

  actualizar() {
    // Calculamos el ángulo usando Ruido Perlin (Noise CHOP)
    let angulo = noise(this.pos.x * parametros.escalaRuido, this.pos.y * parametros.escalaRuido, zOff) * TWO_PI * 4;

    // Convertimos el ángulo en un vector de dirección
    let direccion = p5.Vector.fromAngle(angulo);
    direccion.mult(parametros.fuerzaRuido);

    // Añadimos inercia suave
    this.vel.lerp(direccion, 0.1);
    this.pos.add(this.vel);

    // Si salen de la pantalla, reaparecen en el lado opuesto (Transform TOP wrap)
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.y > height) this.pos.y = 0;
    if (this.pos.y < 0) this.pos.y = height;
  }

  dibujar(buffer) {
    // Efecto Bloom Falso (Dibujar la misma forma más grande y transparente)
    buffer.noStroke();

    // Capa exterior suave (Glow grande)
    let cExterior = color(hue(this.colorBase), saturation(this.colorBase), brightness(this.colorBase), 0.05);
    buffer.fill(cExterior);
    buffer.circle(this.pos.x, this.pos.y, this.grosor * 8);

    // Capa intermedia (Glow medio)
    let cMedio = color(hue(this.colorBase), saturation(this.colorBase), brightness(this.colorBase), 0.2);
    buffer.fill(cMedio);
    buffer.circle(this.pos.x, this.pos.y, this.grosor * 4);

    // Núcleo brillante
    buffer.fill(0, 0, 100, 0.9); // Blanco puro
    buffer.circle(this.pos.x, this.pos.y, this.grosor);
  }
}

// ------------------------------------------
// UI OVERLAY: DATOS Y NODOS SIMULADOS
// ------------------------------------------
function dibujarUI() {
  let margin = 20;

  // Caja de fondo de la interfaz
  noStroke();
  fill(0, 0, 15, 0.7); // Gris oscuro casi opaco
  rect(margin, margin, 260, 200, 5);

  // Marco de la caja (Accent color)
  stroke(180, 100, 100, 0.5); // Borde Cian
  strokeWeight(1);
  noFill();
  rect(margin, margin, 260, 200, 5);

  // Textos
  noStroke();
  fill(0, 0, 100);
  textSize(16);
  text("NETWORK: /project1/generative", margin + 15, margin + 25);

  // Separador
  stroke(0, 0, 50);
  line(margin + 15, margin + 40, margin + 245, margin + 40);

  // Datos simulados (Parámetros)
  noStroke();
  textSize(12);
  fill(180, 50, 100); // Texto Cian pálido

  let currentY = margin + 65;
  let lineSpace = 20;

  text(`FPS (Monitor):       ${floor(frameRate())}`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Instancias (SOP):    ${numParticulas}`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Noise Scale (CHOP):  ${parametros.escalaRuido}`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Feedback Transform:  x${parametros.escalaFeedback}`, margin + 15, currentY);
  currentY += lineSpace;
  text(`Buffer Depth:        32-bit float (Sim)`, margin + 15, currentY);

  // Barra de estado decorativa abajo
  fill(120, 100, 80); // Verde TD
  rect(margin, margin + 195, 260, 5, 0, 0, 5, 5);
}

// Redimensionar el lienzo y el buffer si cambia el tamaño de la ventana
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  // Redimensionamos también el buffer manteniendo el gráfico anterior estirado
  let tempImg = feedbackBuffer.get();
  feedbackBuffer.resizeCanvas(windowWidth, windowHeight);
  feedbackBuffer.image(tempImg, 0, 0, windowWidth, windowHeight);
}

